-- Explicit COLLATE clauses that meet in one expression conflict while the
-- query is analysed, at the later clause, whether or not a row reaches the
-- expression. Implicit collations and separate contexts do not conflict.
CREATE TABLE ec832 (a text, b text, n integer);
SELECT a COLLATE "C" = b COLLATE "POSIX" FROM ec832;
SELECT 1 FROM ec832 WHERE a COLLATE "C" < b COLLATE "POSIX";
SELECT 1 FROM ec832 WHERE false AND a COLLATE "C" = b COLLATE "POSIX";
SELECT a COLLATE "C" || b COLLATE "POSIX" FROM ec832;
SELECT length(a COLLATE "C") + length(b COLLATE "POSIX") FROM ec832;
SELECT strpos(a COLLATE "C", b COLLATE "POSIX") FROM ec832;
SELECT lower(a COLLATE "C") = upper(b COLLATE "POSIX") FROM ec832;
SELECT CASE WHEN n > 0 THEN a COLLATE "C" ELSE b COLLATE "POSIX" END FROM ec832;
SELECT CASE a COLLATE "C" WHEN b COLLATE "POSIX" THEN 1 END FROM ec832;
SELECT ROW(a COLLATE "C", b COLLATE "POSIX") FROM ec832;
SELECT (a COLLATE "C", b) = (b COLLATE "POSIX", a) FROM ec832;
SELECT (a COLLATE "C", b) = (a, b COLLATE "POSIX") FROM ec832;
SELECT a COLLATE "C" IN (b COLLATE "POSIX", 'x') FROM ec832;
SELECT a IN (b COLLATE "POSIX", 'x' COLLATE "C") FROM ec832;
SELECT a COLLATE "C" = ANY (ARRAY[b COLLATE "POSIX"]) FROM ec832;
SELECT (SELECT a COLLATE "C" = b COLLATE "POSIX" FROM ec832);
SELECT 1 FROM ec832 WHERE EXISTS (SELECT 1 FROM ec832 e2 WHERE e2.a COLLATE "C" > ec832.b COLLATE "POSIX");
SELECT max(a COLLATE "C") = max(b COLLATE "POSIX") FROM ec832;
SELECT string_agg(a COLLATE "C", b COLLATE "POSIX") FROM ec832;
SELECT coalesce(a COLLATE "C", b COLLATE "POSIX") FROM ec832;
SELECT greatest(a COLLATE "C", b, 'x' COLLATE "POSIX") FROM ec832;
SELECT ARRAY[a COLLATE "C", b COLLATE "POSIX"] FROM ec832;
SELECT a COLLATE "C" FROM ec832 ORDER BY b COLLATE "POSIX";
SELECT a COLLATE "C" = b COLLATE "C" FROM ec832;
SELECT (a COLLATE "C")::varchar = b COLLATE "POSIX" FROM ec832;
SELECT a COLLATE "C" LIKE b COLLATE "POSIX" FROM ec832;
SELECT a COLLATE "C" ~ b COLLATE "POSIX" FROM ec832;
SELECT n FROM ec832 GROUP BY n HAVING min(a COLLATE "C") > min(b) COLLATE "POSIX";
SELECT e1.a FROM ec832 e1 JOIN ec832 e2 ON e1.a COLLATE "C" = e2.b COLLATE "POSIX";
SELECT 'a' COLLATE "C" = 'b' COLLATE "POSIX";
SELECT a COLLATE "C" = b COLLATE "POSIX" COLLATE "C" FROM ec832;
SELECT a COLLATE "C" IS NULL OR b COLLATE "POSIX" IS NULL FROM ec832;
SELECT row_number() OVER (ORDER BY a COLLATE "C"), b COLLATE "POSIX" FROM ec832;
SELECT a COLLATE "C" = b COLLATE "POSIX" FROM ec832 WHERE n = 1/0;
UPDATE ec832 SET a = 'x' WHERE a COLLATE "C" = b COLLATE "POSIX";
UPDATE ec832 SET a = b COLLATE "C" || a COLLATE "POSIX";
DELETE FROM ec832 WHERE a COLLATE "C" = b COLLATE "POSIX";
DELETE FROM ec832 RETURNING a COLLATE "C" < b COLLATE "POSIX";
BEGIN;
DECLARE ec832_cursor CURSOR FOR SELECT a COLLATE "C" = b COLLATE "POSIX" FROM ec832;
ROLLBACK;
